mapper.update:
UPDATE conversation
SET title = #{title}, title_source = #{titleSource},
    knowledge_base_ids = #{knowledgeBaseIds,typeHandler=org.apache.ibatis.type.ArrayTypeHandler},
    last_asked_at = #{lastAskedAt}
WHERE tenant_id = #{tenantId} AND id = #{id}

mapper.select:
SELECT id, tenant_id, user_id, title, title_source, knowledge_base_ids, last_asked_at
FROM conversation
WHERE tenant_id = #{tenantId} AND id = #{id}
